import {
  Button,
  Card,
  CardHeader,
  CardBody,
  FormGroup,
  Form,
  Input,
  Container,
  Row,
  Col,
  Label,
  Progress,
  Alert,
} from "reactstrap";
import { useState, useEffect } from "react";
import { db, auth } from "../../firebase";
import { collection, addDoc, getDocs, query, where } from "firebase/firestore";

const CarbonDataInput = () => {
  const [carbonData, setCarbonData] = useState({
    date: "",
    category: "",
    value: "",
    unit: "",
    carbonEmission: 0,
  });
  const [impactLevel, setImpactLevel] = useState("Low");
  const [submitted, setSubmitted] = useState(false);
  const [carbonCredits, setCarbonCredits] = useState(0);
  const [carbonReduction, setCarbonReduction] = useState(0);
  const [rank, setRank] = useState("Bronze");

  useEffect(() => {
    if (auth.currentUser) {
      fetchUserStats();
    }
  }, [submitted]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    const updatedData = { ...carbonData, [name]: value };

    if (name === "value" || name === "category") {
      const calculatedEmission = calculateCarbonEmissions(updatedData.category, parseFloat(value) || 0);
      updatedData.carbonEmission = calculatedEmission;
      setImpactLevel(getImpactLevel(calculatedEmission));
    }

    setCarbonData(updatedData);
  };

  const calculateCarbonEmissions = (category, value) => {
    switch (category) {
      case "Transport": return value * 2.31;
      case "Electricity": return value * 0.92;
      case "Diet": return value * 3.5;
      case "Waste": return value * 0.75;
      default: return 0;
    }
  };

  const getImpactLevel = (emission) => {
    if (emission <= 10) return "Low";
    if (emission > 10 && emission <= 50) return "Moderate";
    return "High";
  };

  const calculateCarbonCredits = (carbonEmission) => {
    return Math.max(10 - carbonEmission / 10, 0);
  };

  const determineRank = (credits) => {
    if (credits > 100) return "Gold";
    if (credits > 50) return "Silver";
    return "Bronze";
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!auth.currentUser) {
      alert("Please log in to save your data.");
      return;
    }

    const newCredits = calculateCarbonCredits(carbonData.carbonEmission);
    const updatedCredits = carbonCredits + newCredits;
    const newReduction = (updatedCredits / 100) * 100;

    try {
      await addDoc(collection(db, "carbon_logs"), {
        userId: auth.currentUser.uid,
        date: carbonData.date,
        category: carbonData.category,
        value: carbonData.value,
        unit: carbonData.unit,
        carbonEmission: carbonData.carbonEmission,
        creditsEarned: newCredits,
      });

      setCarbonCredits(updatedCredits);
      setCarbonReduction(newReduction);
      setRank(determineRank(updatedCredits));
      setSubmitted(true);
      setTimeout(() => setSubmitted(false), 3000);
      setCarbonData({ date: "", category: "", value: "", unit: "", carbonEmission: 0 });
    } catch (error) {
      console.error("Error saving data:", error);
      alert("Failed to save data. Please try again.");
    }
  };

  const fetchUserStats = async () => {
    if (!auth.currentUser) return;
    const q = query(collection(db, "carbon_logs"), where("userId", "==", auth.currentUser.uid));
    const querySnapshot = await getDocs(q);

    let totalCredits = 0;
    querySnapshot.forEach((doc) => {
      totalCredits += doc.data().creditsEarned;
    });

    setCarbonCredits(totalCredits);
    setCarbonReduction((totalCredits / 100) * 100);
    setRank(determineRank(totalCredits));
  };

  return (
    <Container className="mt-5" fluid>
      <Row className="justify-content-center">
        <Col lg="8">
          <Card className="bg-dark text-white shadow-lg">
            <CardHeader className="bg-gradient-info text-center">
              <h3 className="mb-0 text-white">🌍 Carbon Tracker</h3>
            </CardHeader>
            <CardBody>
              <Form>
                <Row>
                  <Col md="6">
                    <FormGroup>
                      <Label>Date</Label>
                      <Input type="date" name="date" value={carbonData.date} onChange={handleChange} required />
                    </FormGroup>
                  </Col>
                  <Col md="6">
                    <FormGroup>
                      <Label>Category</Label>
                      <Input type="select" name="category" value={carbonData.category} onChange={handleChange} required>
                        <option value="">Select</option>
                        <option value="Transport">🚗 Transport</option>
                        <option value="Electricity">⚡ Electricity</option>
                        <option value="Diet">🥩 Diet</option>
                        <option value="Waste">🗑 Waste</option>
                      </Input>
                    </FormGroup>
                  </Col>
                </Row>
                <Row>
                  <Col md="6">
                    <h4>Carbon Credits Earned: {carbonCredits.toFixed(2)}</h4>
                    <h5>Carbon Reduction Progress: {carbonReduction.toFixed(2)}%</h5>
                    <h5>Rank: {rank}</h5>
                  </Col>
                </Row>
                <Button color="success" onClick={handleSubmit}>Save Data</Button>
              </Form>
              {submitted && <Alert color="success">✅ Data saved successfully!</Alert>}
            </CardBody>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default CarbonDataInput;
